/* Career Glitch — step details, wave 3 (truck driver).
   Guard pattern (same as details4.js): STEP_DETAILS may already
   exist from details1-4.js; assign into it, never replace it. */
var STEP_DETAILS = (typeof STEP_DETAILS !== "undefined" && STEP_DETAILS) || {};
/* --- TRUCK DRIVER step details (trk-g1..trk-k4) ---
   Links verified by fetching on Nov 1, 2026 (package spec §8 audit):
   BLS OOH, FMCSA registry/CDL pages, Clearinghouse, TSA. */
Object.assign(STEP_DETAILS, {
'trk-g1': {
  what: 'First choose which trucking job you want. Do it before you pay for anything. "Truck driver" is really six jobs: long-haul OTR (over-the-road — weeks away from home), regional, local/LTL city (small mixed loads around town), tanker & hazmat (liquids and dangerous loads), flatbed/heavy haul/car haul, or owner-operator (your own truck).',
  whatRu: 'Сначала выберите, какую работу водителем хотите. Сделайте это до любых трат. «Водитель грузовика» — на деле шесть работ. Дальние рейсы OTR (неделями вне дома). Региональные рейсы. Городские рейсы LTL (развоз мелких грузов по городу). Цистерны и опасные грузы. Платформы, тяжёлые грузы и автовозы. Или свой грузовик.',
  how: ['Read the six verdicts on your result screen. Each job has its own verdict and timeline', 'Write your target job in one sentence, with home time in it ("local, home daily")', 'Check now what this job asks for: years of experience and endorsement letters (extra marks on your licence)', 'Check every later step against this sentence'],
  howRu: ['Прочитайте шесть вердиктов на экране результата. У каждой работы свой вердикт и свои сроки', 'Напишите одним предложением, какую работу хотите и как часто будете дома («город, дома каждую ночь»)', 'Сразу проверьте, что требуют на этой работе: сколько лет опыта и какие буквы-допуски (отметки в правах)', 'Каждый следующий шаг сверяйте с этим предложением'],
  why: 'This choice saves you years. In the age of AI, robot trucks will reach some of these jobs first. The licence is the same for all six jobs. The pay is not. In 37 real job posts, pay goes from $960 a week (long-haul van) to $120,000+ a year (car haul). If you don\'t choose, the first carrier chooses for you. And carriers mostly push long-haul jobs.',
  whyRu: 'Этот выбор экономит вам годы. В эпоху AI грузовики-роботы придут в одни работы раньше, чем в другие. Права одни на все шесть работ. А деньги — разные. В 37 настоящих вакансиях платят от 960 долларов в неделю (дальний фургон) до 120 000+ долларов в год (автовоз). Не выберете сами — выберет первый перевозчик. А они чаще всего зовут в дальние рейсы.',
  links: [{ t: 'BLS — Heavy and Tractor-Trailer Truck Drivers (pay, outlook, what they do)', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-g2': {
  what: 'Check the school before you pay. Since February 2022, federal rules (ELDT, training for new drivers) apply. Your training counts only if the school is in the Training Provider Registry of FMCSA (the US trucking safety agency). Look up the exact school and address there.',
  whatRu: 'Проверьте школу до оплаты. С февраля 2022 года действуют федеральные правила ELDT (обязательная учёба новых водителей). Учёба засчитывается, только если школа есть в реестре FMCSA. Это агентство США по безопасности грузоперевозок. Найдите там точную школу и адрес.',
  how: ['Open the registry (link below) and search the school by name and state', 'Check the exact address where you\'ll study — chains list each site separately', 'Look for the status "active". 9,985 locations have been removed from the registry so far', 'Check again the week training starts. Schools get removed mid-course too'],
  howRu: ['Откройте реестр (ссылка ниже) и найдите школу по названию и штату', 'Проверьте точный адрес, где будете учиться: у сетей каждая точка в списке отдельно', 'Смотрите статус: «активна». Из реестра уже удалили 9 985 точек', 'Проверьте ещё раз в неделю начала учёбы: школы удаляют и посреди курса'],
  why: 'If the school gets removed, your training may not count. Even after you paid. That means lost months and money. The check is free and takes two minutes. It\'s the cheapest protection on your whole path.',
  whyRu: 'Если школу удалят, учёба может не засчитаться. Даже после оплаты. Это потерянные месяцы и деньги. Проверка бесплатная и занимает две минуты. Это самая дешёвая страховка на всём пути.',
  links: [{ t: 'FMCSA — Training Provider Registry (check your school)', u: 'https://tpr.fmcsa.dot.gov/' }]
},
'trk-g3': {
  what: 'Pass two checks before the licence. First, a DOT medical card: a certified doctor checks you can drive safely. Second, your record: the FMCSA Clearinghouse (a list of drug & alcohol violations) and your state driving record (MVR).',
  whatRu: 'До прав пройдите две проверки. Первая — медкарта DOT. Сертифицированный врач проверяет, что вы можете безопасно водить. Вторая — ваша история. Это Clearinghouse от FMCSA (база нарушений по алкоголю и наркотикам). И выписка о вождении от штата (MVR).',
  how: ['Book the DOT medical exam with a certified doctor. Save the card\'s expiry date in your phone', 'Sign up in the Clearinghouse (link below) before your first hiring check', 'Get your state driving record and read it the way a carrier will', 'Fix errors now. A wrong entry a carrier finds can look like a lie'],
  howRu: ['Запишитесь на медосмотр DOT к сертифицированному врачу. Сохраните срок медкарты в телефоне', 'Зарегистрируйтесь в Clearinghouse (ссылка ниже) до первой проверки при найме', 'Возьмите выписку о вождении в своём штате и прочитайте её глазами перевозчика', 'Исправьте ошибки сейчас. Неверная запись, которую найдёт перевозчик, может выглядеть как ложь'],
  why: 'Every carrier in our 37 job posts runs these checks. City (LTL) job posts say it directly: "no DUI within the last 5 years", "able to obtain a medical card". Check your record before they do. Fix problems early, and no job offer falls through later.',
  whyRu: 'Все перевозчики из наших 37 вакансий делают эти проверки. Городские вакансии пишут прямо: «без DUI (езды в нетрезвом виде) за последние 5 лет», «способность получить медкарту». Проверьте себя раньше них. Исправите заранее — и предложение работы не сорвётся.',
  links: [{ t: 'FMCSA Clearinghouse — student driver page', u: 'https://clearinghouse.fmcsa.dot.gov/Learn/Student-Driver' }, { t: 'FMCSA — How do I get a commercial driver’s license?', u: 'https://www.fmcsa.dot.gov/registration/commercial-drivers-license/how-do-i-get-commercial-drivers-license' }]
},
'trk-g4': {
  what: 'Now get the Class A CDL (the licence for big trucks). First, pass written tests for a learner\'s permit (CLP). Then train at a school from the registry. Then pass a 3-part driving test: pre-trip inspection, basic vehicle control, on-road driving.',
  whatRu: 'Теперь получите CDL класса A — права на большой грузовик с прицепом. Сначала сдайте письменные тесты на ученическое разрешение (CLP). Потом учитесь в школе из реестра. Потом сдайте экзамен из 3 частей: осмотр перед рейсом, базовое управление, вождение по дороге.',
  how: ['Pass the state written tests and get the CLP. Ask ChatGPT or Claude to quiz you on the manual. You must be 21 to drive between states', 'Finish ELDT training at a school from the registry (you checked it in the last step)', 'Choose the gearbox on purpose: testing in an automatic adds an "E — no manual" limit to your license', 'In our 37 job posts, automatic trucks are normal and most carriers accept the limit. A few (one car-haul carrier) prefer manual', 'Pass the 3-part driving test. Check your license shows the class and limits you expect'],
  howRu: ['Сдайте письменные тесты штата и получите CLP. Попросите ChatGPT или Claude погонять вас по учебнику. Для рейсов между штатами вам должен быть 21 год', 'Пройдите обучение ELDT в школе из реестра (вы проверили её на прошлом шаге)', 'Выберите коробку передач осознанно: экзамен на автомате ставит в права ограничение «E — без механики»', 'В наших 37 вакансиях автомат — норма, и большинство перевозчиков принимают ограничение. Но некоторые (один перевозчик автовозов) хотят механику', 'Сдайте экзамен из 3 частей. Проверьте, что в правах нужные класс и ограничения'],
  why: 'In the age of AI, this licence protects your job. A robot truck needs new laws to compete with you. A foreign worker needs a visa. Get the licence clean, with limits you chose yourself. Then every better-paid job stays open to you.',
  whyRu: 'В эпоху AI эти права защищают вашу работу. Грузовику-роботу нужны новые законы, чтобы с вами соперничать. Иностранцу — виза. Получите права чисто, с ограничениями, которые выбрали сами. Тогда все денежные работы останутся для вас открытыми.',
  links: [{ t: 'FMCSA — Drivers (classes, endorsements T/N/H/X, the E restriction)', u: 'https://www.fmcsa.dot.gov/registration/commercial-drivers-license/drivers' }, { t: 'FMCSA — How do I get a commercial driver’s license?', u: 'https://www.fmcsa.dot.gov/registration/commercial-drivers-license/how-do-i-get-commercial-drivers-license' }]
},
'trk-g5': {
  what: 'Choose how to pay for school. Option one: a private or community-college school (about $3,000–$10,000). You pay, and you stay free. Option two: a carrier\'s "free" school. The carrier pays, but you sign a work contract. Leave early and you get a bill, commonly $3,000–$7,000.',
  whatRu: 'Решите, как платить за учёбу. Вариант первый: частная школа или колледж (около 3 000–10 000 долларов). Платите вы — и остаётесь свободны. Вариант второй: «бесплатная» школа перевозчика. Платит он, но вы подписываете рабочий контракт. Уйдёте раньше — получите счёт, обычно 3 000–7 000 долларов.',
  how: ['Write down the price of both options, for equally good schools from the registry', 'If a carrier pays, get in writing before you sign: contract length, payback amount, what happens if THEY fire you', 'Compare the payback bill with the pay difference. A contract that keeps you in the worst-paid job can cost more than school', 'Never let the way you pay pick your job. You already chose the job in step 1'],
  howRu: ['Запишите цену обоих вариантов для одинаково хороших школ из реестра', 'Если платит перевозчик, до подписи получите письменно: срок контракта, сумму возврата и что будет, если уволят ВАС', 'Сравните сумму возврата с разницей в зарплате. Контракт, который держит вас на самой низкооплачиваемой работе, может стоить дороже учёбы', 'Не позволяйте способу оплаты выбирать вам работу. Работу вы уже выбрали на шаге 1'],
  why: 'Paying yourself is often the faster way to good money. With no contract, you can leave at month 12 for a better job. With a contract, you get the same licence, but you\'re stuck. $3,000–$10,000 spent on the one risky job is the costly way in.',
  whyRu: 'Заплатить самому — часто быстрый путь к хорошим деньгам. Без контракта вы уйдёте на 12-й месяц на работу получше. С контрактом права те же, но уйти нельзя. 3 000–10 000 долларов на единственную рискованную работу — самый дорогой вход.',
  links: [{ t: 'FMCSA — Training Provider Registry (compare listed schools before pricing)', u: 'https://tpr.fmcsa.dot.gov/' }]
},
'trk-p1': {
  what: 'Look at your first driving job in a new way. Its main prize is not the paycheck. It\'s 12 clean months on your record. The YES jobs here (LTL city, tanker, car haul) ask for 1–2 years of experience.',
  whatRu: 'Посмотрите на первую работу по-новому. Главное в ней — не зарплата. Главное — 12 чистых месяцев в вашей истории. Работы с вердиктом ДА (городские рейсы, цистерны, автовозы) просят 1–2 года опыта.',
  how: ['Take a first job you can stick with. 13 of 37 job posts hire new CDL holders — mostly long-haul and team driving', 'Write down your move date (month 12) now, while the job is new', 'One rule for the year: no avoidable accident. That\'s worth more than any sign-on bonus', 'Compare your weekly pay with posted pay for your job type. Two months in a row below that is a sign, not bad luck'],
  howRu: ['Берите первую работу, на которой сможете продержаться. 13 из 37 вакансий берут новичков с CDL — в основном дальние рейсы и работа в паре', 'Запишите дату перехода (12-й месяц) сейчас, пока работа новая', 'Одно правило на год: ни одной аварии по вашей вине. Это дороже любого бонуса за выход', 'Сравнивайте свою недельную оплату с тем, сколько платят на вашей работе по вакансиям. Два месяца подряд ниже — это сигнал, а не невезение'],
  why: 'Year one is your shortcut to the better jobs. Big long-haul carriers have lost about 94% of drivers a year. The ones who move up aren\'t the toughest. They treat year one as savings with an end date. You can do that too.',
  whyRu: 'Первый год — ваш короткий путь к лучшим работам. Крупные дальнобойные компании теряли около 94% водителей в год. Наверх выходят не самые выносливые. А те, кто видит первый год как вклад с датой снятия. У вас тоже получится.',
  links: [{ t: 'BLS — about 214,500 openings a year, most of them replacements', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-p2': {
  what: 'Add extra letters (endorsements) to your CDL. Each one is a written test. Hazmat (dangerous loads) also needs a federal background check. The letters: N (tanker), T (doubles/triples), then H (hazmat). N+H together show as X.',
  whatRu: 'Добавьте в права CDL дополнительные буквы-допуски. Каждая — это письменный тест. Для опасных грузов нужна ещё федеральная проверка биографии. Буквы: N (цистерна), T (двойные и тройные прицепы), потом H (опасные грузы). N+H вместе печатаются как X.',
  how: ['Start with N and T: written tests only, no extra school', 'Apply for the hazmat TSA check early — $85.25 (or $41 if you have TWIC). Waiting is the slow part', 'Pass the hazmat written test after TSA approves you', 'Check your license shows the letters; carriers verify them electronically'],
  howRu: ['Начните с N и T: только письменные тесты, отдельная школа не нужна', 'Подайте на проверку TSA для опасных грузов заранее: 85,25 доллара (или 41 доллар, если есть TWIC). Дольше всего — ждать ответа', 'Сдайте тест по опасным грузам, когда TSA вас одобрит', 'Проверьте, что буквы есть в правах: перевозчики проверяют их онлайн'],
  why: 'This is the fastest pay jump on your path. Hazmat is in 18 of 37 job posts, tanker in 14, doubles/triples in 11. Every city LTL job post asks for some or all of them. Three letters can move you from $960 a week to $36 an hour.',
  whyRu: 'Это самый быстрый рост оплаты на всём пути. Опасные грузы есть в 18 из 37 вакансий, цистерна — в 14, двойные и тройные прицепы — в 11. Каждая городская вакансия просит часть этих букв или все. Три буквы — это путь от 960 долларов в неделю к 36 долларам в час.',
  links: [{ t: 'TSA — Hazardous Materials Endorsement (HME)', u: 'https://www.tsa.gov/for-industry/hazmat-endorsement' }, { t: 'FMCSA — Drivers (endorsement codes T / N / H / X)', u: 'https://www.fmcsa.dot.gov/registration/commercial-drivers-license/drivers' }]
},
'trk-p3': {
  what: 'Get the TWIC card (Transportation Worker Identification Credential) when you need it. It\'s a pass from TSA into ports, chemical plants and rail yards without an escort. Some of the best-paid loads are there.',
  whatRu: 'Получите карту TWIC, когда она понадобится. Это пропуск от TSA (служба транспортной безопасности США). С ним вы проходите в порты, на химзаводы и ж/д терминалы без сопровождения. Там часть самых дорогих грузов.',
  how: ['Apply online with TSA, then enroll in person with documents (link below)', 'New applicant fee: $124. With TWIC, your hazmat check costs only $41', 'Get it when your target job goes to ports, plants or rail — not before', 'Keep its expiry date next to your medical card date. Drivers get fired over both'],
  howRu: ['Подайте заявку онлайн в TSA, потом придите лично с документами (ссылка ниже)', 'Новый заявитель платит 124 доллара. С TWIC проверка для опасных грузов стоит всего 41 доллар', 'Получайте её, когда ваша работа связана с портами, заводами или железной дорогой. Не раньше', 'Держите её срок рядом со сроком медкарты: из-за просрочки обеих в этой профессии увольняют'],
  why: 'TWIC is in only 3 of 37 job posts. But those jobs carry valuable, guarded loads: tanker and port work. It\'s a cheap key to them. Get it when your job starts asking for it. Not earlier.',
  whyRu: 'TWIC есть только в 3 из 37 вакансий. Но там дорогие, охраняемые грузы: цистерны и порты. Это дешёвый ключ к ним. Получайте его, когда работа начнёт его просить. Раньше не тратьтесь.',
  links: [{ t: 'TSA — TWIC (Transportation Worker Identification Credential)', u: 'https://www.tsa.gov/for-industry/twic' }]
},
'trk-p4': {
  what: 'Start a clean-record folder, on paper or in your phone. Keep every clean roadside inspection, your Clearinghouse status, medical card, employer letters and safety awards. Good jobs hire based on this.',
  whatRu: 'Заведите папку чистой истории — бумажную или в телефоне. Храните каждую чистую проверку на дороге, статус в Clearinghouse, медкарту, письма работодателей и награды за безопасность. На хорошие работы берут именно по ней.',
  how: ['Save every inspection report, clean or not — clean ones are gold', 'Photograph documents the day you get them. Paper gets lost in trucks; phones keep a copy', 'Once a year, pull your Clearinghouse and state records and compare them to your file', 'Bring the folder when you apply — LTL and tanker hiring checks exactly this'],
  howRu: ['Сохраняйте каждый акт проверки, чистый или нет. Чистые — на вес золота', 'Фотографируйте документы в день получения. Бумага теряется в кабине, а телефон сохраняет копию', 'Раз в год берите свои записи из Clearinghouse и штата и сверяйте с папкой', 'Берите папку, когда подаётесь: в городских рейсах и цистернах проверяют именно это'],
  why: 'Carriers have drivers. They lack good ones. The chief economist of ATA (the US trucking industry group) calls it "a quality problem, not a quantity problem". Your folder proves you\'re one of the good ones. That gets you hired faster.',
  whyRu: 'Водителей много, а хороших мало. Главный экономист ATA (ассоциация грузоперевозчиков США) называет это «проблемой качества, а не количества». Ваша папка доказывает, что вы из хороших. Так вас берут быстрее.',
  links: [{ t: 'FMCSA Clearinghouse — your record and registration', u: 'https://clearinghouse.fmcsa.dot.gov/Learn/Student-Driver' }]
},
'trk-p5': {
  what: 'Learn one hands-on cargo skill for your target job. Flatbed: tying down loads and covering them with tarps. Tanker: loading, unloading and handling liquid sloshing. Car haul: loading and moving cars.',
  whatRu: 'Освойте один ручной навык с грузом под вашу работу. Платформа: крепить груз и укрывать брезентом. Цистерна: грузить, разгружать и справляться с раскачкой жидкости. Автовоз: грузить и возить машины.',
  how: ['Pick the skill your target job asks for — read its job posts again', 'Practise it on purpose and photograph your best work (your quest album starts here)', 'Learn to spot problems too: what bad tie-down or loading looks like before you drive', 'Keep proof: photos, trainer sign-offs, any carrier certification'],
  howRu: ['Выберите навык, который требует ваша работа: перечитайте её вакансии', 'Тренируйте его специально и фотографируйте лучшие результаты (здесь начинается ваш альбом для квестов)', 'Научитесь видеть ошибки: как выглядит плохое крепление или погрузка, пока вы не тронулись', 'Храните доказательства: фото, подписи инструкторов, сертификаты перевозчика'],
  why: 'AI and robots won\'t take this part soon. BLS (the US labor statistics office) says drivers "secure the cargo using ropes, chains, or covers" and may load and unload. A robot can drive. But a human still tarps the steel. Be that human, and get paid like a specialist.',
  whyRu: 'AI и роботы не скоро заберут эту часть. BLS (статистика труда США) пишет: водители «крепят груз верёвками, цепями или укрытиями». Ещё они могут грузить и разгружать. Робот умеет вести машину. А брезент на сталь натягивает человек. Будьте этим человеком — и получайте как специалист.',
  links: [{ t: 'BLS — What heavy truck drivers do (cargo, loading, inspections)', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-k1': {
  what: 'Time to move up. At 12–24 months, with experience and endorsements, apply for the YES job from step 1. That\'s LTL city, tanker, flatbed specialty, car haul or linehaul (long runs between hubs).',
  whatRu: 'Время подняться выше. На 12–24-й месяц, с опытом и допусками, подавайтесь на работу с вердиктом ДА из шага 1. Это городские рейсы, цистерны, особые грузы на платформах, автовозы или магистральные рейсы между терминалами.',
  how: ['Apply while you still have a job. These jobs want a working driver with a clean record', 'Add your record folder (last step) and endorsement letters to every application', 'Compare offers by total pay and nights at home. Use your best-week number from the quests', 'Don\'t quit over a spoken promise. Get the written offer and start date first'],
  howRu: ['Подавайтесь, пока ещё работаете. Эти работы ищут работающего водителя с чистой историей', 'Прикладывайте папку истории (прошлый шаг) и буквы-допуски к каждой заявке', 'Сравнивайте предложения по общей оплате и ночам дома. Берите за ориентир свою лучшую неделю из квестов', 'Не увольняйтесь из-за устного обещания. Сначала письменное предложение и дата выхода'],
  why: 'This is where the better pay starts. Job posts name the experience: 1 year for LTL city, 2 years for car haul, 2 years plus flatbed time for heavy haul. So these jobs open at month 12–24. This move is your reward for the first two stages.',
  whyRu: 'Здесь начинаются хорошие деньги. Вакансии прямо пишут, какой нужен опыт. Городские рейсы — 1 год, автовозы — 2 года. Тяжёлые грузы — 2 года плюс опыт на платформах. Значит, эти работы открываются на 12–24-й месяц. Этот переход — ваша награда за два первых этапа.',
  links: [{ t: 'BLS — job outlook: about 214,500 openings per year', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-k2': {
  what: 'Learn how drivers get paid. The same driving can pay per mile, as a percent of the load, hourly, or per task (per stop, per trailer move, unloading fees). Turn any plan into one number: dollars per week. Then compare.',
  whatRu: 'Разберитесь, как платят водителям. За одно и то же вождение платят по-разному: за милю, процент от груза, почасово или за действия (за остановку, перецепку прицепа, разгрузку). Переведите любую схему в одно число — доллары в неделю. Потом сравнивайте.',
  how: ['Take one real pay stub or offer and work out: total pay ÷ weeks, and pay per night away. ChatGPT or Claude can do the sum with you in a minute', 'Count what is NOT paid: waiting, loading time, deadhead miles (driving empty)', 'Check when bonuses pay out: sign-on bonuses in our job posts pay over 12 months', 'If a recruiter can\'t show the plan in writing, expect the lowest pay in its range'],
  howRu: ['Возьмите реальный расчётный лист или предложение и посчитайте: общая оплата ÷ недели и оплата за ночь вне дома. ChatGPT или Claude посчитают с вами за минуту', 'Посчитайте, что НЕ оплачивается: ожидание, время погрузки, холостые мили (пустой пробег)', 'Смотрите, когда платят бонусы: бонусы за выход в наших вакансиях выплачивают в течение 12 месяцев', 'Если рекрутер не может показать схему письменно, рассчитывайте на минимум'],
  why: 'This math gets you to top pay faster. Posted numbers hide the details. One local job post pays $0.68/mile plus $20 per stop plus $50 per trailer move. Good or bad? You only know after you add up a real week. Drivers who count stop working for free.',
  whyRu: 'Этот счёт быстрее ведёт к высокой оплате. Цифры в вакансии прячут детали. Одна городская вакансия: 0,68 доллара за милю, плюс 20 долларов за остановку, плюс 50 долларов за перецепку прицепа. Много или мало? Видно, только если посчитать реальную неделю. Кто считает, перестаёт работать бесплатно.',
  links: [{ t: 'BLS — pay distribution: bottom 10% under $40,140, top 10% over $79,380', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-k3': {
  what: 'Do the math on owning your truck, honestly. You get a percent of the load (80–87% in offers we saw). Then subtract fuel, insurance (one carrier lists $298/week), their trailer rent ($250–$450/week), repairs, taxes and unpaid empty miles.',
  whatRu: 'Честно посчитайте доход на своём грузовике. Вы получаете процент от груза (80–87% в предложениях, которые мы видели). Вычтите топливо и страховку (у одного перевозчика 298 долларов в неделю). Вычтите аренду их прицепа (250–450 долларов в неделю), ремонт, налоги и неоплаченные пустые мили.',
  how: ['Build the spreadsheet from your own year of company driving (your bill-file quest data). Ask ChatGPT or Claude to set up the table — an evening, not a week', 'Work out one real week at 80%, 85% and 87%. The percent is what you bargain over', 'Honestly compare it with your company pay for the same week, benefits included', 'Avoid the trap: lease-purchase where the carrier selling you the truck also controls your loads'],
  howRu: ['Соберите таблицу по своему году работы в компании (данные из квеста про расходы). Попросите ChatGPT или Claude сделать таблицу — это вечер, а не неделя', 'Посчитайте одну реальную неделю при 80%, 85% и 87%. О проценте вы и торгуетесь', 'Честно сравните с оплатой в компании за ту же неделю, включая льготы', 'Избегайте ловушки: лизинг с выкупом, где перевозчик продаёт вам грузовик и сам же даёт грузы'],
  why: 'One carrier\'s own example: $8,000 in a week becomes about $4,500 after costs. Good money, but about half the big number. 161,500 drivers (7.3%) work this way, and some do great. Do the math before you sign. Then you skip the costly mistake.',
  whyRu: 'Пример самого перевозчика: 8 000 долларов за неделю — это около 4 500 после расходов. Хорошие деньги, но почти вдвое меньше громкой цифры. Так работают 161 500 водителей (7,3%), и у многих получается. Посчитайте до подписи. Так вы обойдёте дорогую ошибку.',
  links: [{ t: 'BLS — 161,500 of 2,221,200 drivers are self-employed (7%)', u: 'https://www.bls.gov/ooh/transportation-and-material-moving/heavy-and-tractor-trailer-truck-drivers.htm' }]
},
'trk-k4': {
  what: 'Every quarter, check your routes against self-driving trucks. Compare the roads you really drive with published robot-truck routes. Today that\'s Aurora\'s list; Kodiak\'s and Torc\'s when they launch. Also watch FMCSA rule changes.',
  whatRu: 'Раз в квартал сверяйте свои маршруты с беспилотными грузовиками. Сравните дороги, где реально ездите, с опубликованными трассами беспилотников. Сегодня это список Aurora; Kodiak и Torc — когда запустятся. И следите за правилами FMCSA.',
  how: ['List your three most common lanes, honestly', 'Check each one against the current self-driving route lists in your Radar', 'Note the cargo type: dry van terminal-to-terminal is at risk; hazmat is left out of the federal self-driving rule relief (Oct 2026) for now', 'If your route shows up, start planning your job change. Go back to step k1 with fresh eyes'],
  howRu: ['Честно перечислите три своих самых частых маршрута', 'Сверьте каждый с текущими списками беспилотных трасс в вашем Радаре', 'Отметьте тип груза: сухой фургон от терминала до терминала — под угрозой; опасные грузы пока не входят в федеральные послабления для беспилотных (октябрь 2026)', 'Если ваш маршрут там появился, пора планировать смену работы. Вернитесь к шагу k1 свежим взглядом'],
  why: 'This is your protection in the age of AI. Self-driving trucks arrive route by route, in public. By February 2026 there were five Aurora routes, all Sun Belt interstates (the US South). Check every quarter and you get years of warning. That\'s plenty of time to move.',
  whyRu: 'Это ваша защита в эпоху AI. Беспилотники приходят маршрут за маршрутом, и всё это публично. К февралю 2026 было пять трасс Aurora. Все — межштатные трассы на юге США. Проверяйте раз в квартал — и узнаете за годы. Этого хватит, чтобы спокойно перейти.',
  links: [{ t: 'FMCSA — driverless-truck beacon exemption, Oct 7 2026 (hazmat excluded)', u: 'https://www.fmcsa.dot.gov/sites/fmcsa.dot.gov/files/2026-10/Aurora%20Operations%20Exemption_10-07-2026.pdf' }, { t: 'Aurora — 250,000 driverless miles, the lane list (Feb 11, 2026)', u: 'https://www.businesswire.com/news/home/20260211346263/en/Aurora-Triples-Driverless-Network-to-10-Routes-and-Prepares-to-Expand-Across-U.S.-Sun-Belt' }]
}
});

/* --- MENTAL HEALTH COUNSELOR step details (cns-g1..cns-k4) ---
   Links: only URLs returned verbatim by search/fetch on Nov 1, 2026
   (BLS, NBCC, IDFPR, Arizona board, per package spec §8). */
Object.assign(STEP_DETAILS, {
'cns-g1': {
  what:'A counselor helps people through stress, sadness and hard times by talking. First, pick which of five counseling jobs you want. Do it before you spend money. Good choices: a licensed group or private practice, or a community agency. Two to avoid as final goals: app-based gig work and the certificate-only path.',
  how:['Read the five rows on your result card one more time.','Write the one job you\'re aiming for, in one line.','Under it, write the two NO jobs. Now you know what to skip.'],
  why:'This choice saves you years of wrong turns. AI already writes notes for counselors. But licensed people keep the therapy itself — the part that pays well. We looked at 44 job posts. One title hides five very different pay levels. The bottom pays $43 an hour. The top pays $135,000 a year. The job you aim for decides which you get.',
  whatRu:'Консультант помогает людям пережить стресс, грусть и трудные времена через разговор. Сначала выберите, к какой из пяти работ идёте. Сделайте это до любых трат. Хорошие варианты: своя или групповая практика с лицензией или общественное агентство. Не делайте конечной целью два варианта: подработку через приложение и путь только с сертификатом.',
  howRu:['Ещё раз прочитайте пять строк в карточке результата.','Запишите одной строкой работу, к которой идёте.','Под ней запишите две работы NO. Так понятно, чего избегать.'],
  whyRu:'Этот выбор избавит вас от лишних лет. AI уже пишет за консультантов записи. Но саму терапию оставляют людям с лицензией — и за неё хорошо платят. Мы посмотрели 44 вакансии. За одним названием — пять очень разных зарплат. Внизу платят $43 в час. Наверху — $135,000 в год. Какую получите вы, решает ваша цель.',
  links:[{t:'BLS — Substance Abuse, Behavioral Disorder & Mental Health Counselors (official pay and outlook)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-g2': {
  what:'Choose a 60-credit master\'s in counseling that your state accepts. Your state board gives licences, and it must accept the degree. CACREP (the national group that checks counseling programs) is the safest pick. A few states require a CACREP degree.',
  how:['Open your state board\'s page on what schooling you need for the counselor licence.','Check how many credits it asks for (usually 60) and whether CACREP is required or just OK.','Compare your program with that page, in writing, before your next tuition payment.','If the program is not CACREP and the board doesn\'t count it as equal, stop and rethink. This really matters.'],
  why:'The wrong degree is the most costly mistake here. A master\'s can cost $40,000–$100,000 or more. If the board doesn\'t accept it, you get no licence. Employers check this. Thriveworks asks for “a graduate of an approved 60-credit hour program.” Check early, and you never study twice.',
  whatRu:'Выберите магистратуру по консультированию на 60 кредитов (учебных единиц). Её должен принимать совет вашего штата — он выдаёт лицензии. Самый надёжный вариант — программа с CACREP. Это национальная проверка программ. Некоторые штаты требуют именно её.',
  howRu:['Откройте на сайте совета вашего штата, какое образование нужно для лицензии консультанта.','Посмотрите, сколько кредитов нужно (обычно 60) и нужен ли CACREP или он просто подходит.','Сверьте свою программу с этой страницей, письменно, до следующей оплаты учёбы.','Если программа не CACREP и совет не считает её равной — остановитесь и подумайте. Это очень важно.'],
  whyRu:'Неправильный диплом — самая дорогая ошибка здесь. Магистратура стоит $40,000–$100,000 и больше. Если совет её не примет, лицензии не будет. Работодатели это проверяют. Thriveworks пишет: «выпускник одобренной программы на 60 кредитов». Проверьте заранее — и учиться дважды не придётся.',
  links:[{t:'BLS — how this occupation is entered (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'},
         {t:'NBCC — National Certified Counselor eligibility (official)', u:'https://community.nbcc.org/certification/ncc'}]},
'cns-g3': {
  what:'Pass the licence exam your state board names. It\'s either the NCE (200 multiple-choice questions) or the NCMHCE (practice with made-up client cases). NBCC (the national counselors\' board) runs both.',
  how:['On your state board\'s page, find which exam it accepts. Many states take either one.','Sign up through NBCC when your board says you can. Some states let you take it during your supervised years.','Study for the exam you\'ll really take: questions for the NCE, client cases for the NCMHCE. Ask ChatGPT or Claude to make practice questions or cases for you.','Keep your passing score report with your licence papers.'],
  why:'No exam, no licence, and most good jobs stay closed. 30 of 44 job posts need the full licence. Bonus: NBCC uses the same two exams for its own certificate. One exam, two wins.',
  whatRu:'Сдайте экзамен на лицензию, который называет совет вашего штата. Это NCE (200 вопросов с вариантами ответа) или NCMHCE (разбор придуманных случаев с клиентами). Оба проводит NBCC — национальный совет консультантов.',
  howRu:['Найдите на сайте совета вашего штата, какой экзамен он принимает. Многие штаты — любой из двух.','Запишитесь через NBCC, когда совет разрешит. В некоторых штатах можно сдавать в годы под супервизией (работы под присмотром опытного коллеги).','Готовьтесь к тому экзамену, который будете сдавать: вопросы для NCE, случаи с клиентами для NCMHCE. Попросите ChatGPT или Claude сделать вам тренировочные вопросы или случаи.','Храните результат экзамена вместе с документами на лицензию.'],
  whyRu:'Без экзамена нет лицензии — и хорошие работы закрыты. Полную лицензию требуют 30 из 44 вакансий. Бонус: NBCC берёт те же два экзамена для своего сертификата. Один экзамен — две победы.',
  links:[{t:'NBCC — NCC eligibility: the NCE / NCMHCE requirement (official)', u:'https://community.nbcc.org/certification/ncc'}]},
'cns-g4': {
  what:'Plan your supervised years before they start. Supervised means you work while an experienced, licensed counselor guides you. Write down three things: your state\'s hour total (2,000–3,000 hours in the states we checked), your approved supervisor, and where the hours will come from.',
  how:['Write your state’s exact hour number at the top of the plan (state examples: Connecticut 3,000 + 100 supervision hours; Texas 3,000; Illinois 3,360; Florida 1,500 face-to-face hours over at least 100 weeks).','Find out which supervisor your board approves. Usually it\'s a licensed counselor (or other licensed clinician) who is allowed to supervise.','Split the hours over months. At 25 client sessions a week (the usual load in job posts), it takes about two years.','Decide now: will your employer give you supervision, or will you pay for it? That\'s the next step, cns-g5.'],
  why:'Many plans get stuck here, not at the degree. Beginners earn $40,000–$65,000 in these years. Hours without an approved supervisor don\'t count at all. A good plan saves you months. You\'ll get through.',
  whatRu:'Спланируйте годы под супервизией ещё до старта. Супервизия — это когда вы работаете, а опытный коллега с лицензией вас направляет. Запишите три вещи. Сколько часов нужно в вашем штате (от 2,000 до 3,000 часов в штатах, которые мы смотрели). Кто ваш супервизор, одобренный советом. И откуда возьмутся часы.',
  howRu:['Запишите точное число часов вашего штата в начале плана (примеры: Коннектикут — 3,000 + 100 часов супервизии; Техас — 3,000; Иллинойс — 3,360; Флорида — 1,500 часов вживую с клиентами минимум за 100 недель).','Узнайте, какого супервизора одобряет ваш совет. Обычно это лицензированный консультант (или другой лицензированный специалист), которому можно вести супервизию.','Разделите часы на месяцы. При 25 сессиях с клиентами в неделю (обычная нагрузка в вакансиях) выходит около двух лет.','Решите сейчас: супервизию даст работодатель или вы оплатите её сами? Это следующий шаг, cns-g5.'],
  whyRu:'Многие планы застревают именно здесь, а не на дипломе. Новичкам в эти годы платят $40,000–$65,000. Часы без одобренного супервизора не засчитываются совсем. Хороший план сбережёт вам месяцы. Вы пройдёте.',
  links:[{t:'NBCC — supervised experience standard: 3,000 hours + 100 supervision hours (official)', u:'https://community.nbcc.org/certification/ncc'}]},
'cns-g5': {
  what:'Before you say yes to a beginner job, get the supervision deal in writing. Who supervises you? Does the board approve them? How often do you meet? Who pays?',
  how:['Ask the question in the interview, in these words: “Who is my clinical supervisor, and is the supervision board-approved toward licensure?”','Ask if supervision is one-on-one, in a group, or both, and how hours get recorded.','If they don\'t give supervision, find out what a private approved supervisor costs before saying yes. That money comes out of your salary.','Get the answer into your offer letter. A spoken promise from a recruiter doesn\'t count.'],
  why:'Free supervision saves you money for two years. Ten job posts offer it in writing (Thriveworks, Ellie Mental Health, Helio Health, GearingUp, Daybreak Health). Elsewhere, the beginner pays for it from a $40,000–$65,000 salary. So ask. It\'s a normal question.',
  whatRu:'Прежде чем согласиться на работу новичка, получите условия супервизии письменно. Кто ваш супервизор? Одобрил ли его совет штата? Как часто вы встречаетесь? Кто платит?',
  howRu:['Задайте вопрос на собеседовании этими словами: «Кто мой клинический супервизор, и одобрена ли супервизия советом в счёт лицензии?»','Спросите, супервизия один на один, в группе или и так, и так, и как записываются часы.','Если супервизию не дают, до согласия узнайте, сколько стоит частный одобренный супервизор. Эти деньги уйдут из вашей зарплаты.','Попросите вписать это в письмо с предложением работы. Устное обещание рекрутера не считается.'],
  whyRu:'Бесплатная супервизия экономит вам деньги два года. Десять вакансий дают её письменно (Thriveworks, Ellie Mental Health, Helio Health, GearingUp, Daybreak Health). В других местах новичок платит сам из зарплаты $40,000–$65,000. Так что спрашивайте. Это нормальный вопрос.',
  links:[{t:'BLS — pay and outlook for this occupation (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-p1': {
  what:'Finish the practice hours inside your degree: 100 practicum hours and 600 internship hours. That\'s real places, real clients, with a supervisor guiding you.',
  how:['Pick internship places that match the job you want. A group practice or agency is better than a place unrelated to your plan.','Write down your hours every week from week one — in the program\'s system and in your own copy.','Ask each supervisor there for one written review per term, and keep it.','Treat your internship like your first job interview. Places in our search hire their own interns.'],
  why:'These 700 hours are your shortcut to a first job. Employers look at them first. They\'re also the base of your licence papers. And it\'s the only time supervision comes free with school.',
  whatRu:'Отработайте часы практики во время учёбы: 100 часов практикума и 600 часов стажировки. Это настоящие места, настоящие клиенты и супервизор рядом.',
  howRu:['Выбирайте места стажировки под работу, которую хотите. Групповая практика или агентство лучше, чем место, не связанное с вашим планом.','Записывайте часы каждую неделю с самой первой — в системе программы и в своей копии.','Просите у каждого супервизора на месте один письменный отзыв за семестр и храните его.','Считайте стажировку первым собеседованием. Места из нашего поиска берут своих стажёров на работу.'],
  whyRu:'Эти 700 часов — короткий путь к первой работе. Работодатели смотрят на них первыми. На них же стоят документы на лицензию. И только сейчас супервизия бесплатно входит в учёбу.',
  links:[{t:'NBCC — education and examination standards (official)', u:'https://community.nbcc.org/certification/ncc'}]},
'cns-p2': {
  what:'Write down every supervised hour, every week, in two places: your employer\'s system and your own copy. Note the date, the hours, the type of client contact, and the supervision you got.',
  how:['Set a 10-minute weekly date with yourself to log hours.','Write client hours and total hours separately. Boards count them differently.','Have your supervisor sign or confirm the log regularly, not at year\'s end.','Keep the file after you leave the job. Boards can check old logs.'],
  why:'Hours you don\'t write down don\'t count, in every state. Log weekly, and you finish the 2,000–3,000 hours on time. Try to remember them all at the end, and you lose months. Ten minutes a week keeps your path short.',
  whatRu:'Записывайте каждый час под супервизией, каждую неделю, в двух местах: в системе работодателя и в своей копии. Отмечайте дату, часы, вид работы с клиентом и полученную супервизию.',
  howRu:['Назначьте себе 10 минут в неделю на запись часов.','Записывайте часы с клиентами и общие часы отдельно. Советы штатов считают их по-разному.','Пусть супервизор подписывает или подтверждает журнал регулярно, а не в конце года.','Храните файл и после ухода с работы. Советы могут проверить старые записи.'],
  whyRu:'Незаписанные часы не считаются — во всех штатах. Записываете каждую неделю — и проходите от 2,000 до 3,000 часов вовремя. Вспоминаете всё в конце — теряете месяцы. Десять минут в неделю держат путь коротким.',
  links:[{t:'NBCC — documented, supervised experience requirement (official)', u:'https://community.nbcc.org/certification/ncc'}]},
'cns-p3': {
  what:'Learn one named therapy method that employers ask for: CBT (cognitive behavioral therapy), DBT (dialectical behavior therapy), EMDR (trauma work), or motivational interviewing.',
  how:['Look at 10 job posts for the job you want. Count which method names show up. AI can count them in minutes. Learn the one that repeats most.','Choose a real course with practice and feedback, not a one-hour webinar.','Try the method first with clients your supervisor watches over, and tell them about it.','Write the full method name on your resume. Job posts look for these exact words.'],
  why:'This is your road to top pay. No job post asks for a “good listener”. They ask for named methods. Changing Paths NC lists CBT, DBT and motivational interviewing. A named specialty moves you from general work to $75,000–$135,000 practice pay.',
  whatRu:'Хорошо освойте один известный метод терапии, который просят в вакансиях: CBT (когнитивно-поведенческая терапия), DBT (диалектическая поведенческая терапия), EMDR (работа с травмой) или мотивационное интервью.',
  howRu:['Посмотрите 10 вакансий на работу, которую хотите. Посчитайте, какие методы там названы. AI посчитает за минуты. Учите тот, что встречается чаще.','Выберите настоящее обучение с практикой и разбором, а не часовой вебинар.','Сначала пробуйте метод с клиентами под супервизией и рассказывайте об этом супервизору.','Напишите полное название метода в резюме. Вакансии ищут именно эти слова.'],
  whyRu:'Это ваша дорога к высокой оплате. Ни одна вакансия не просит «хорошего слушателя». Просят методы по названию. Changing Paths NC прямо пишет CBT, DBT и мотивационное интервью. Метод с названием ведёт от общей работы к зарплатам практики $75,000–$135,000.',
  links:[{t:'BLS — what employers and settings look like for this occupation (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-p4': {
  what:'Learn the computer system for client notes your employer uses. Our search found Epic, Netsmart Avatar and AthenaOne. Build a habit of quick, tidy notes. Use AI note tools only where your employer and state allow it.',
  how:['In the interview, ask which notes system they use. Write it down.','Learn the system’s note templates in your first month, not your sixth.','Time how long your notes take for one week. Make a rule to finish them the same day.','Know your state\'s rule. In Illinois, licensed pros can use AI for helper tasks. Never for therapy decisions or talking with clients.'],
  why:'In the age of AI, notes and paperwork are what AI is really taking over. The talking stays human. Counselors who know the system go home on time. Those who fight it lose their evenings. You can be the first kind.',
  whatRu:'Освойте программу для записей о клиентах, которую использует работодатель. В вакансиях мы нашли Epic, Netsmart Avatar и AthenaOne. Привыкайте делать записи быстро и аккуратно. AI-помощников для записей используйте только там, где разрешают работодатель и штат.',
  howRu:['На собеседовании спросите, в какой программе ведут записи. Запишите.','Освойте шаблоны записей в первый месяц, а не в шестой.','Неделю замеряйте, сколько времени уходит на записи. Поставьте себе правило: заканчивать в тот же день.','Знайте правило своего штата. В Иллинойсе лицензированные специалисты могут использовать AI для вспомогательных задач. Но не для решений о терапии и не для общения с клиентами.'],
  whyRu:'В эпоху AI он правда забирает записи и бумаги. А разговор с человеком остаётся вам. Кто хорошо знает программу, уходит домой вовремя. Кто с ней воюет, теряет вечера. Вы можете быть из первых.',
  links:[{t:'Illinois IDFPR — the WOPR Act: what AI may and may not do in therapy (official state release)', u:'https://idfpr.illinois.gov/news/2025/gov-pritzker-signs-state-leg-prohibiting-ai-therapy-in-il.html'}]},
'cns-p5': {
  what:'Get ready the papers insurance companies need before they pay for your sessions. That\'s your NPI (national provider number), your CAQH profile (an online file insurers check), and your licence papers. Keep them all in one folder.',
  how:['Get or confirm your NPI number if your job needs one.','Make your CAQH profile and keep its papers up to date. Job posts ask for CAQH by name.','Keep license, diploma, exam score and supervision records as scans in one place.','When you join a practice, ask who handles insurance approval and how long it takes. You can only start paid sessions after that.'],
  why:'No insurance papers, no paid clients. Daybreak Health\'s job post asks for an active NPI and CAQH by name. Group practices do the same, because insurers set this rule. Ready papers mean you start earning sooner.',
  whatRu:'Подготовьте бумаги, без которых страховые не платят за ваши сессии. Это NPI (национальный номер специалиста), профиль в CAQH (онлайн-досье, которое смотрят страховые) и документы на лицензию. Держите всё в одной папке.',
  howRu:['Получите номер NPI или проверьте его, если он нужен для вашей работы.','Создайте профиль в CAQH и обновляйте документы. Вакансии прямо просят CAQH.','Храните сканы лицензии, диплома, результата экзамена и записей супервизии в одном месте.','Когда придёте в практику, спросите, кто оформляет вас у страховых и сколько это занимает. Платные сессии начнутся только после этого.'],
  whyRu:'Без бумаг для страховых нет платных клиентов. Вакансия Daybreak Health прямо просит действующие NPI и CAQH. Групповые практики тоже: это правило ставят страховые. Бумаги готовы — и вы начинаете зарабатывать раньше.',
  links:[{t:'BLS — work settings and pay by setting (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-k1': {
  what:'Choose where to work by how they pay. Write it down. It\'s a salary, productivity pay (money based on how many clients you see), or pay per live session. Before signing, find out what is NOT paid in each.',
  how:['Take your two best offers. Write how each one pays, in one line.','Under each, list what\'s unpaid: notes, missed sessions, meetings, preparation.','Count a real week: 25 client sessions is a normal full week in beginner job posts. Licensed practice pay assumes about the same.','Pick the pay type whose unpaid parts you can live with — not the biggest number in the ad.'],
  why:'The same licence pays $43 an hour (sessions only, on an app), $68,000–$75,000 (agency salary, 95 billable hours expected) or $75,000–$135,000 (practice, paid per client). How they pay is the real job. The big number is just an ad.',
  whatRu:'Выбирайте место работы по тому, как там платят. Запишите. Бывает зарплата, оплата за число клиентов или оплата за каждую живую сессию. До подписи узнайте, что в каждом варианте НЕ оплачивается.',
  howRu:['Возьмите два лучших предложения. Запишите одной строкой, как платят в каждом.','Под каждым перечислите, что не оплачивается: записи, неявки клиентов, совещания, подготовку.','Посчитайте реальную неделю: 25 сессий с клиентами — обычная полная неделя в вакансиях для новичков. В практиках с лицензией — примерно так же.','Выберите вариант, где неоплаченные части вам подходят, — а не самую большую цифру в объявлении.'],
  whyRu:'Одна и та же лицензия даёт $43 в час (только сессии, через приложение), $68,000–$75,000 (зарплата в агентстве, норма 95 оплачиваемых часов) или $75,000–$135,000 (практика, оплата за клиентов). Настоящая работа — это то, как платят. Большая цифра — просто реклама.',
  links:[{t:'BLS — median $59,350 and pay by setting (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-k2': {
  what:'The Counseling Compact is a deal between states. It lets a licensed counselor work in other member states. When your state joins for real, ask for permission to work in the states you want.',
  how:['Check the compact map for two things: is your home state live, and are the states you want live?','Note the gap: 39 states and DC passed the law, but only 11 could give permissions in October 2026.','Apply in the compact\'s system (CompactConnect) for each state separately.','Don\'t see clients in a state where you have no licence or permission. Online sessions follow this rule too.'],
  why:'More states means more pay. One licence opens several states. No second degree, no second round of hours. It only started on 30 September 2025. So if you\'re early, there\'s little competition across state lines.',
  whatRu:'Counseling Compact — это договор между штатами. С ним консультант с лицензией может работать в других штатах договора. Когда ваш штат по-настоящему подключится, получите разрешение работать в нужных вам штатах.',
  howRu:['Проверьте карту договора: подключён ли ваш штат и подключены ли штаты, которые вам нужны.','Помните разницу: 39 штатов и DC приняли закон, но выдавать разрешения в октябре 2026 года могли только 11.','Подавайте в системе договора (CompactConnect) отдельно на каждый штат.','Не принимайте клиентов в штате, где у вас нет ни лицензии, ни разрешения. Для онлайн-сессий правило то же.'],
  whyRu:'Больше штатов — больше заработок. Одна лицензия открывает несколько штатов. Без второго диплома и второго круга часов. Это заработало только 30 сентября 2025 года. Кто успеет рано, встретит мало конкурентов в других штатах.',
  links:[{t:'Arizona Board of Behavioral Health Examiners — Counseling Compact status (official state board)', u:'https://bbhe.az.gov/counseling-compact'}]},
'cns-k3': {
  what:'Build a circle of people who send you clients. Think psychiatrists, family doctors, school counselors, past supervisors and internship places. They meet your future clients before you do.',
  how:['List 10 names from your training years: supervisors, coworkers, classmates now working elsewhere.','Send two short, clear messages a month: what you help with, who you help most, one open spot. AI can help you draft them.','Thank everyone who sends you a client. With the client\'s OK, share a one-line update.','Track where your last 10 clients came from. That list is your real marketing, not ads.'],
  why:'In private practice, no one hands you clients. Even big group practices promise “consistent referrals” as a perk. Clients sent by others are hard to find. In your own practice, you bring them in. That\'s how top earners fill their week. You can do it, one message at a time.',
  whatRu:'Соберите круг людей, которые будут направлять к вам клиентов. Это психиатры, семейные врачи, школьные психологи, бывшие супервизоры и места интернатуры. Они встречают ваших будущих клиентов раньше вас.',
  howRu:['Запишите 10 имён со времён учёбы: супервизоры, коллеги, одногруппники, которые теперь работают в других местах.','Отправляйте два коротких понятных сообщения в месяц: с чем вы помогаете, кому особенно и одно свободное время. AI поможет набросать текст.','Благодарите каждого, кто прислал клиента. С согласия клиента одной строкой расскажите, как дела.','Отмечайте, откуда пришли последние 10 клиентов. Этот список — ваш настоящий маркетинг, а не реклама.'],
  whyRu:'В частной практике клиентов вам никто не приводит. Даже большие практики обещают «стабильные направления» как бонус. Клиентов по рекомендации найти трудно. В своей практике их приводите вы. Так лучшие специалисты заполняют неделю. У вас получится — по одному сообщению за раз.',
  links:[{t:'BLS — job outlook: +98,000 jobs, about 50,500 openings a year (official)', u:'https://www.bls.gov/ooh/Community-and-social-service/substance-abuse-behavioral-disorder-and-mental-health-counselors.htm'}]},
'cns-k4': {
  what:'Once a year, check your state and your pay again. Look at its AI-therapy law and its compact status. Compare your pay with new job posts. And ask: is supervisor or clinical lead your next step up?',
  how:['Put a yearly date in your calendar: board rules, compact map, a fresh look at job posts for your job.','Read one radar issue for this job and mark what changed.','If you supervise or could, know it\'s worth money. Job posts list paid supervisor roles (Thriveworks) and use free supervision to attract people. Supervision is a paid skill now.','Change one thing a year: a rate, a specialty, a state permission, or a role. Doing nothing is a choice too, and it has a cost.'],
  why:'AI is changing this job fast. Three states passed AI-therapy laws in 2025. The compact went from law to working. Check once a year, and nothing catches you off guard. You stay ahead of most counselors.',
  whatRu:'Раз в год заново проверяйте свой штат и свою оплату. Посмотрите закон об AI-терапии и подключение к договору штатов. Сравните оплату со свежими вакансиями. И спросите себя: может, следующий шаг — стать супервизором или руководителем?',
  howRu:['Поставьте в календарь дату раз в год: правила совета, карта договора, свежие вакансии на вашу работу.','Прочитайте один выпуск радара по этой профессии и отметьте, что изменилось.','Если вы ведёте супервизию или могли бы — это стоит денег. Вакансии предлагают оплачиваемые роли супервизора (Thriveworks) и бесплатную супервизию, чтобы привлечь людей. Супервизия теперь — оплачиваемый навык.','Меняйте одну вещь в год: ставку, специальность, разрешение штата или роль. Ничего не менять — тоже выбор, и у него есть цена.'],
  whyRu:'AI быстро меняет эту профессию. Три штата приняли законы об AI-терапии в 2025 году. Договор штатов из закона стал работающим. Проверяйте раз в год — и ничто не застанет вас врасплох. Так вы будете впереди большинства коллег.',
  links:[{t:'Illinois IDFPR — AI therapy law release (official)', u:'https://idfpr.illinois.gov/news/2025/gov-pritzker-signs-state-leg-prohibiting-ai-therapy-in-il.html'},
         {t:'Arizona Board — Counseling Compact page (official)', u:'https://bbhe.az.gov/counseling-compact'}]}
});
